using System;
using System.Collections.Generic;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;
namespace LumaDesk {
public class ClockCity {public string Name,ZoneId,IanaId;public override string ToString(){return Name;}}
public static class WorldClocks {
 static readonly Dictionary<string,TimeZoneInfo> zones=new Dictionary<string,TimeZoneInfo>();
 public static readonly ClockCity[] Cities={
  City("Нью-Йорк","Eastern Standard Time","America/New_York"),City("Токио","Tokyo Standard Time","Asia/Tokyo"),City("Москва","Russian Standard Time","Europe/Moscow"),City("Санкт-Петербург","Russian Standard Time","Europe/Moscow"),City("Саратов","Saratov Standard Time","Europe/Saratov"),City("Самара","Russia Time Zone 3","Europe/Samara"),City("Калининград","Kaliningrad Standard Time","Europe/Kaliningrad"),City("Екатеринбург","Ekaterinburg Standard Time","Asia/Yekaterinburg"),City("Омск","Omsk Standard Time","Asia/Omsk"),City("Новосибирск","N. Central Asia Standard Time","Asia/Novosibirsk"),City("Красноярск","North Asia Standard Time","Asia/Krasnoyarsk"),City("Иркутск","North Asia East Standard Time","Asia/Irkutsk"),City("Якутск","Yakutsk Standard Time","Asia/Yakutsk"),City("Владивосток","Vladivostok Standard Time","Asia/Vladivostok"),City("Петропавловск-Камчатский","Russia Time Zone 11","Asia/Kamchatka"),City("Берлин","W. Europe Standard Time","Europe/Berlin"),City("Париж","Romance Standard Time","Europe/Paris"),City("Лондон","GMT Standard Time","Europe/London"),City("Стамбул","Turkey Standard Time","Europe/Istanbul"),City("Дубай","Arabian Standard Time","Asia/Dubai"),City("Пекин","China Standard Time","Asia/Shanghai"),City("Сеул","Korea Standard Time","Asia/Seoul"),City("Сингапур","Singapore Standard Time","Asia/Singapore"),City("Дели","India Standard Time","Asia/Kolkata"),City("Сидней","AUS Eastern Standard Time","Australia/Sydney"),City("Лос-Анджелес","Pacific Standard Time","America/Los_Angeles"),City("Чикаго","Central Standard Time","America/Chicago"),City("Торонто","Eastern Standard Time","America/Toronto")};
 static ClockCity City(string name,string windows,string iana){return new ClockCity{Name=name,ZoneId=windows,IanaId=iana};}
 public static List<ClockCity> Defaults(){return new List<ClockCity>{CloudJson.Copy(Cities[0]),CloudJson.Copy(Cities[1])};}
 public static ClockCity Get(State s,int index){return s.WorldCities!=null&&index<s.WorldCities.Count&&s.WorldCities[index]!=null?s.WorldCities[index]:Cities[index==0?0:1];}
 public static TimeZoneInfo Zone(ClockCity city){string key=city.ZoneId+"|"+city.IanaId;lock(zones){TimeZoneInfo found;if(zones.TryGetValue(key,out found))return found;foreach(string id in new[]{city.ZoneId,city.IanaId})if(!string.IsNullOrEmpty(id))try{found=TimeZoneInfo.FindSystemTimeZoneById(id);zones[key]=found;return found;}catch{}}throw new ArgumentException("Часовой пояс недоступен. Выбери другой из списка Windows.");}
 public static DateTime AtUtc(ClockCity city,DateTime utc){return TimeZoneInfo.ConvertTimeFromUtc(DateTime.SpecifyKind(utc,DateTimeKind.Utc),Zone(city));}
 public static string Time(State s,int index,DateTime local){try{return AtUtc(Get(s,index),local.ToUniversalTime()).ToString("HH:mm");}catch{return "--:--";}}
}
public class ClockCityForm:ChromeForm {
 ListBox list;TextBox name,search;ComboBox zone;Label hint;ClockCity selected;public ClockCity Result;
 public ClockCityForm(ClockCity current,int slot){Text="Город мирового времени";SetContentSize(540,452);Controls.Add(new Label{Text=slot==0?"Первый город":"Второй город",Bounds=new Rectangle(24,20,490,35),ForeColor=EditorArt.Text,Font=Theme.F(17,FontStyle.Bold)});search=Theme.Input("",24,67,492);search.AccessibleName="Поиск города";Controls.Add(search);list=new ListBox{Bounds=new Rectangle(24,109,492,150),BackColor=EditorArt.Panel,ForeColor=EditorArt.Text,BorderStyle=BorderStyle.None,Font=Theme.F(11)};Controls.Add(list);Controls.Add(Theme.Label("Название города",24,280,220));Controls.Add(Theme.Label("Часовой пояс",254,280,262));name=Theme.Input(current.Name,24,309,218);name.MaxLength=32;Controls.Add(name);zone=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,BackColor=EditorArt.Panel,ForeColor=EditorArt.Text,FlatStyle=FlatStyle.Flat,Bounds=new Rectangle(254,309,262,30)};foreach(var z in TimeZoneInfo.GetSystemTimeZones().OrderBy(z=>z.BaseUtcOffset))zone.Items.Add(z);Controls.Add(zone);hint=Theme.Label("Можно выбрать город или задать своё название и часовой пояс.",24,353,492);hint.Height=34;Controls.Add(hint);Select(current);list.SelectedIndexChanged+=(s,e)=>{var city=list.SelectedItem as ClockCity;if(city!=null)Select(city);};search.TextChanged+=(s,e)=>Fill();list.DoubleClick+=(s,e)=>Save();Controls.Add(new SmoothButton("Отмена",new Rectangle(24,399,150,36),(s,e)=>{DialogResult=DialogResult.Cancel;Close();}));Controls.Add(new SmoothButton("Сохранить",new Rectangle(354,399,162,36),(s,e)=>Save()){Primary=true});Fill();}
 void Fill(){list.Items.Clear();foreach(var city in WorldClocks.Cities.Where(c=>c.Name.IndexOf(search.Text.Trim(),StringComparison.CurrentCultureIgnoreCase)>=0).OrderBy(c=>c.Name))list.Items.Add(city);}
 void Select(ClockCity city){selected=city;name.Text=city.Name;try{var resolved=WorldClocks.Zone(city);for(int i=0;i<zone.Items.Count;i++)if(((TimeZoneInfo)zone.Items[i]).Id==resolved.Id){zone.SelectedIndex=i;return;}}catch{}zone.SelectedIndex=-1;}
 void Save(){if(string.IsNullOrWhiteSpace(name.Text)||zone.SelectedItem==null){hint.Text="Укажи название и выбери часовой пояс.";hint.ForeColor=AppTheme.Error;return;}var z=(TimeZoneInfo)zone.SelectedItem;string iana=null;if(selected!=null)try{if(WorldClocks.Zone(selected).Id==z.Id)iana=selected.IanaId;}catch{}Result=new ClockCity{Name=name.Text.Trim(),ZoneId=z.Id,IanaId=iana};DialogResult=DialogResult.OK;Close();}
}
}
